import base64, binascii
from pydantic import BaseModel, ValidationError, field_validator

def decode_b64(value, expected, name):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a Base64-encoded string")
    try:
        raw = base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError):
        raise ValueError(f"{name} must be standard Base64 (RFC 4648)") from None
    # b64decode(validate=True) accepts urlsafe chars? ensure standard alphabet
    if base64.b64encode(raw).decode() != value:
        raise ValueError(f"{name} must use standard Base64 with canonical padding")
    if len(raw) != expected:
        raise ValueError(f"{name} must decode to exactly {expected} bytes")
    return raw

class M(BaseModel):
    pk: bytes
    sig: bytes

    @field_validator("pk", mode="before")
    @classmethod
    def v_pk(cls, v):
        return decode_b64(v, 32, "public_key")

    @field_validator("sig", mode="before")
    @classmethod
    def v_sig(cls, v):
        return decode_b64(v, 64, "signature")

pk32 = base64.b64encode(b"a" * 32).decode()
sig64 = base64.b64encode(b"s" * 64).decode()
m = M.model_validate({"pk": pk32, "sig": sig64})
print("ok:", len(m.pk), len(m.sig), type(m.pk))

urlsafe = base64.urlsafe_b64encode(b"a" * 32).decode()  # contains - or _ maybe
candidates = ["@@@", "aGVsbG8", urlsafe, "not base64!!", "YWJj", "",
              base64.b64encode(b"a" * 31).decode(), base64.b64encode(b"a" * 33).decode(),
              "YWFh", "AAAA", 123, None]
for bad in candidates:
    try:
        M.model_validate({"pk": bad, "sig": sig64})
        print("ACCEPTED(?):", repr(bad)[:30])
    except ValidationError as e:
        print("rejected:", repr(bad)[:30], "->", e.errors()[0]["msg"][:50])

